import { XIcon } from 'lucide-react'
import { Dialog as DialogPrimitive } from 'radix-ui'

import { Button } from '@/components/ui/button'

function Dialog({ ...props }: React.ComponentProps<typeof DialogPrimitive.Root>) {
  return <DialogPrimitive.Root data-slot="dialog" {...props} />
}

function DialogTrigger({ ...props }: React.ComponentProps<typeof DialogPrimitive.Trigger>) {
  return <DialogPrimitive.Trigger data-slot="dialog-trigger" {...props} />
}

function DialogPortal({ ...props }: React.ComponentProps<typeof DialogPrimitive.Portal>) {
  return (
    <DialogPrimitive.Portal container={usePortalContainer()} data-slot="dialog-portal" {...props} />
  )
}

function DialogClose({ ...props }: React.ComponentProps<typeof DialogPrimitive.Close>) {
  return <DialogPrimitive.Close data-slot="dialog-close" {...props} />
}

function DialogOverlay({
  className,
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Overlay>) {
  return (
    <DialogPrimitive.Overlay
      data-slot="dialog-overlay"
      className={cn(
        'fixed inset-0 z-50 bg-black/50 data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:animate-in data-[state=open]:fade-in-0',
        className,
      )}
      {...props}
    />
  )
}

function DialogContent({
  className,
  children,
  showCloseButton = true,
  draggable,
  resizable,
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Content> & {
  showCloseButton?: boolean
  draggable?: boolean
  resizable?: boolean
}) {
  const [position, setPosition] = React.useState({ x: 0, y: 0 }),
    drag = React.useRef<{
      x: number
      y: number
      px: number
      py: number
      limitX: number
      limitY: number
    } | null>(null)
  return (
    <DialogPortal data-slot="dialog-portal">
      <DialogOverlay />
      <DialogPrimitive.Content
        data-slot="dialog-content"
        className={cn(
          'fixed top-[50%] left-[50%] z-50 grid w-full max-w-[calc(100%-2rem)] translate-x-[-50%] translate-y-[-50%] gap-4 rounded-lg border bg-background p-6 shadow-lg duration-200 outline-none data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=closed]:zoom-out-95 data-[state=open]:animate-in data-[state=open]:fade-in-0 data-[state=open]:zoom-in-95 sm:max-w-lg',
          className,
        )}
        {...props}
        style={{
          ...(draggable
            ? {
                transform: `translate(calc(-50% + ${position.x}px),calc(-50% + ${position.y}px))`,
                translate: 'none',
              }
            : {}),
          ...(resizable
            ? {
                resize: 'both',
                width: 'min(512px,calc(100vw - 32px))',
                overflow: 'auto',
                minWidth: 260,
                minHeight: 150,
                maxWidth: 'calc(100vw - 32px)',
                maxHeight: 'calc(100vh - 32px)',
              }
            : {}),
          ...props.style,
        }}
        onPointerDown={(event) => {
          props.onPointerDown?.(event)
          if (
            !draggable ||
            (event.target as HTMLElement).closest('button,input,textarea,select,a') ||
            !(event.target as HTMLElement).closest(
              '[data-slot="dialog-header"],[data-slot="dialog-title"]',
            )
          )
            return
          const bounds = event.currentTarget.getBoundingClientRect()
          drag.current = {
            x: event.clientX,
            y: event.clientY,
            px: position.x,
            py: position.y,
            limitX: Math.max(0, (innerWidth - bounds.width) / 2 - 16),
            limitY: Math.max(0, (innerHeight - bounds.height) / 2 - 16),
          }
          event.currentTarget.setPointerCapture(event.pointerId)
        }}
        onPointerMove={(event) => {
          props.onPointerMove?.(event)
          if (drag.current)
            setPosition({
              x: Math.max(
                -drag.current.limitX,
                Math.min(drag.current.limitX, drag.current.px + event.clientX - drag.current.x),
              ),
              y: Math.max(
                -drag.current.limitY,
                Math.min(drag.current.limitY, drag.current.py + event.clientY - drag.current.y),
              ),
            })
        }}
        onPointerUp={(event) => {
          drag.current = null
          props.onPointerUp?.(event)
        }}
        onLostPointerCapture={() => {
          drag.current = null
        }}
      >
        {children}
        {showCloseButton && (
          <DialogPrimitive.Close
            data-slot="dialog-close"
            className="absolute top-4 right-4 rounded-xs opacity-70 ring-offset-background transition-opacity hover:opacity-100 focus:ring-2 focus:ring-ring focus:ring-offset-2 focus:outline-hidden disabled:pointer-events-none data-[state=open]:bg-accent data-[state=open]:text-muted-foreground [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4"
          >
            <XIcon />
            <span className="sr-only">Close</span>
          </DialogPrimitive.Close>
        )}
      </DialogPrimitive.Content>
    </DialogPortal>
  )
}

function DialogHeader({ className, ...props }: React.ComponentProps<'div'>) {
  return (
    <div
      data-slot="dialog-header"
      className={cn('flex flex-col gap-2 text-center sm:text-left', className)}
      {...props}
    />
  )
}

function DialogFooter({
  className,
  showCloseButton = false,
  children,
  ...props
}: React.ComponentProps<'div'> & {
  showCloseButton?: boolean
}) {
  return (
    <div
      data-slot="dialog-footer"
      className={cn('flex flex-col-reverse gap-2 sm:flex-row sm:justify-end', className)}
      {...props}
    >
      {children}
      {showCloseButton && (
        <DialogPrimitive.Close asChild>
          <Button variant="outline">Close</Button>
        </DialogPrimitive.Close>
      )}
    </div>
  )
}

function DialogTitle({ className, ...props }: React.ComponentProps<typeof DialogPrimitive.Title>) {
  return (
    <DialogPrimitive.Title
      data-slot="dialog-title"
      className={cn('text-lg leading-none font-semibold', className)}
      {...props}
    />
  )
}

function DialogDescription({
  className,
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Description>) {
  return (
    <DialogPrimitive.Description
      data-slot="dialog-description"
      className={cn('text-sm text-muted-foreground', className)}
      {...props}
    />
  )
}

export {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogOverlay,
  DialogPortal,
  DialogTitle,
  DialogTrigger,
}

import { contrastForeground } from '@/lib/contrast'
import * as React from 'react'
import { cn } from '@/lib/utils'
import { Direction } from 'radix-ui'
export interface UIConfig {
  density: 'comfortable' | 'compact'
  direction: 'ltr' | 'rtl'
  locale: string
}
const ConfigContext = React.createContext<UIConfig>({
  density: 'comfortable',
  direction: 'ltr',
  locale: 'en-US',
})
const PortalContext = React.createContext<HTMLElement | null>(null)
export const usePortalContainer = () => React.useContext(PortalContext) ?? undefined
export const useUIConfig = () => React.useContext(ConfigContext)
export interface ConfigProviderProps extends React.HTMLAttributes<HTMLDivElement> {
  density?: UIConfig['density']
  direction?: UIConfig['direction']
  locale?: string
  accent?: string
  radius?: number
}
export function ConfigProvider({
  density: providedDensity,
  direction: providedDirection,
  locale: providedLocale,
  accent,
  radius,
  children,
  style,
  className,
  ...props
}: ConfigProviderProps) {
  const parent = useUIConfig(),
    density = providedDensity ?? parent.density,
    direction = providedDirection ?? parent.direction,
    locale = providedLocale ?? parent.locale
  const [portal, setPortal] = React.useState<HTMLDivElement | null>(null)
  return (
    <ConfigContext.Provider value={{ density, direction, locale }}>
      <PortalContext.Provider value={portal}>
        <Direction.Provider dir={direction}>
          <div
            dir={direction}
            lang={locale}
            data-density={density}
            className={cn('ergon-root', className)}
            style={
              {
                ...(accent
                  ? {
                      '--primary': accent,
                      '--ring': accent,
                      '--primary-foreground': contrastForeground(accent),
                    }
                  : {}),
                ...(radius !== undefined ? { '--radius': `${radius}px` } : {}),
                ...style,
              } as React.CSSProperties
            }
            {...props}
          >
            {children}
            <div ref={setPortal} data-ergon-portals="" style={{ display: 'contents' }} />
          </div>
        </Direction.Provider>
      </PortalContext.Provider>
    </ConfigContext.Provider>
  )
}
